Q: WebAPI2 / Angular job Interview skill assessment [SHARE] - NULL values A: <p>Only took 9 years and some experience.</p>
<p>First. Stop relying on visual studio templates, I know it works but you really dont know what's going on behind the scenes</p>
<p>Therefore:</p>
<p>for the LINQ part in HomeController.cs (generated by visual studio ) it needed to be changed to:</p>
<pre class="lang-cs prettyprint-override"><code>namespace KLab.Controllers {
  public class HomeController: Controller {
    public ActionResult Index() {
      ViewBag.Title = &quot;Home Page&quot;;

      return View();
    }
    public JsonResult GetSections() {
      var db = new KLabDBEntities();

      db.Configuration.ProxyCreationEnabled = false;

      var samples = db.Samples
        .Include(&quot;User&quot;)
        .Include(&quot;Status&quot;)
        .ToList();

      return Json(samples, JsonRequestBehavior.AllowGet);
