<p>Cross.pl</p>
<pre><code># Cross.pl
# (creates intermediate files)

use strict;
use warnings;

## PARSE INPUT PARAMS
##

my $usage = 
 &quot;\nUsage:  Cross.pl  -  Intermediate file generator\n\n&quot;.
 &quot;   Reqd:  &lt;In=word-file-name-in.txt&gt;  input name of dictionary (single word/line)\n&quot;.
 &quot;          &lt;ws=3-#&gt;  word size ranges (3 letters minimum)\n&quot;.
 &quot;          &lt;ws=-1&gt;   or  -1 will do all sizes\n\n&quot;.
 &quot;   Opt:   &lt;Out=file-name-out-root&gt;  prepended to '#Ltr.txt' output name\n&quot;.
 &quot;          &lt;rx=[st]&gt; filter regex, calls Cross_Qry.pl\n&quot;.
 &quot;          &lt;dist=1&gt;  1 or 2 ? print letter distribution.  2 ? then exits\n&quot;.
 &quot;          &lt;quiet&gt;   supress word list display of generated difs\n&quot;;
;
if ( @ARGV &lt; 2 ) {
  die ( $usage );
}

my ($fname, $out, $wslo, $wshi, $rxstr, $dist, $quiet) = (&quot;&quot;, &quot;&quot;, 0, 0, &quot;&quot;, 0, 0);
my $p;

for ( $p = 0; $p &lt; @ARGV; $p++ ) {   # Get dictionary file name
   if ( $ARGV[$p] =~ /(?i)^In=(.+)/ ) {
      $fname = $1;
      last;   
   }}
for ( $p = 0; $p &lt; @ARGV; $p++ ) {   # Get output file name seed
   if ( $ARGV[$p] =~ /(?i)^Out=(.+)/ ) {
      $out = $1;
      last;   
   }}
for ( $p = 0; $p &lt; @ARGV; $p++ ) {   # Get word size
   if ( $ARGV[$p] =~ /(?i)^Ws=(-1|[3-9]|[1-9]\d+)(?:-(\d+))?/ ) {
      $wslo = $1;
      if ( defined($2) &amp;&amp; $2 &gt;= $1 ) {
         $wshi = $2;
      } else { $wshi = $wslo; }
      if ( $wshi &gt; 999 ) {
         $wshi = 999;
      }
      last;   
   }}
for ( $p = 0; $p &lt; @ARGV; $p++ ) {   # Get regex string
   if ( $ARGV[$p] =~ /(?i)^Rx=(.+)/ ) {
      $rxstr = $1;
      last;
   }}
for ( $p = 0; $p &lt; @ARGV; $p++ ) {   # Get distribution flag
   if ( $ARGV[$p] =~ /(?i)^Dist=(\d)/ ) {
      $dist = $1;
      last;   
   }}
for ( $p = 0; $p &lt; @ARGV; $p++ ) {   # Get quiet flag
   if ( $ARGV[$p] =~ /(?i)^quiet/ ) {
      $quiet = 1;
      last;   
   }}

if ( $fname eq &quot;&quot; ) {
   die ( &quot;$usage-------\nWord file Dictionary name required,  'In=...'\n&quot;);
}
if ( $wslo == 0 &amp;&amp; $dist != 2 ) {
   die ( &quot;$usage-------\nWord size required,  'ws=3-#' range or 'ws=-1' all sizes\n&quot;);
}

## Print paramater info
print &quot;\n&quot;, &quot;Input File Dictionary = $fname\n&quot;;
print &quot;Word size Range = &quot;;
if ( $dist != 2 )
{
   if ( $wslo == -1 ) { print &quot;-1 (all)&quot;;}
   else { print &quot;$wslo-$wshi&quot;; }
   print &quot;\n&quot;;

   print &quot;Output File Seed = $out + '#Ltr.txt'\n&quot; if ( $out ne &quot;&quot; );
   print &quot;Regex query =  $rxstr  (will call 'Cross_Qry.pl')\n&quot; if ($rxstr ne &quot;&quot; );
}
else
{ print &quot;N/A\n&quot;; }
print &quot;Letter distribution show = $dist &quot;;
print &quot; (yes, then exit)\n&quot; if ( $dist == 2 );
print &quot; (yes)\n&quot; if ( $dist == 1 );
print &quot; (no)\n&quot; if ( $dist == 0 );


## Open the dictionary file and read in the words
##
open(my $fh, &quot;&lt;&quot;, $fname) or die &quot;Cannot open Dictionary file '$fname' for reading: $!&quot;;

my @AllLines = ();

while (my $line = &lt;$fh&gt;)
{
   chomp($line);
   $line =~ s/^\s+|\s+$//g;
   if ( length($line) &gt; 0 )
   {
      push ( @AllLines, $line );
      # print $line, &quot;\n&quot;;
   }
}
close($fh); 

my $showLtrDistribution = $dist;  # == 1 ? Print letter distribution
                                  # == 2 ? Print distribution then exit

## GET LETTER DISTRIBUTION ##

my %HDistCnts = ();
my %HDistAry = ();
my $dlen;

foreach my $Owd (@AllLines)
{
   $dlen = length( $Owd );
   if (defined($HDistCnts{ $dlen })) {
      ++$HDistCnts{ $dlen };
   }
   else {
      $HDistCnts{ $dlen } = 0;
      $HDistAry{ $dlen } = [];
   }
   if ( $showLtrDistribution != 2 ) {
      push ( @{$HDistAry{ $dlen }}, $Owd );
   }
}
if ( $showLtrDistribution &gt; 0 )
{
   print (&quot;Total sample = &quot;, scalar(@AllLines), &quot;  words\nMax letter size in words = &quot;, scalar(keys(%HDistCnts)), &quot;\n\n&quot;);

   foreach my $key (sort { $a &lt;=&gt; $b } keys %HDistCnts) {
      printf ( &quot;%2d letters  @  $HDistCnts{ $key }  words\n&quot;, $key );
   }
   if ( $showLtrDistribution &gt; 1 ) {
      exit();
   }
   print ( &quot;\n&quot; );
}

@AllLines = ();   # clear unneeded array

## Set the word size loop variables
##
my ($Wd_Start, $Wd_End) = (0, 0);

if ( $wslo == -1 ) {
   $Wd_Start = 3;
   $Wd_End = 99;
}
else {
   $Wd_Start = $wslo;
   $Wd_End = $wshi;
}


## LOOP WORD SIZES ##
##
for ( my $width = $Wd_Start; $width &lt;= $Wd_End; $width++ )
{
   # Does there exist letters of this width
   if ( !defined($HDistAry{ $width }) ) {
      next;
   }

   print &quot;\n\nDiffs-by-one of $width length words\n&quot;;

   my $pre_fout = sprintf( &quot;%s_%02d&quot;, $out, $width);
   my $fout = $pre_fout . &quot;Ltr.txt&quot;;

   print &quot;Intermediate Output File:  $fout\n--------------------------------------------------\n&quot;;

   # Open the output file
   #
   open(my $fho, &quot;+&gt;&quot;, $fout) or die &quot;Cannot open file '$fout' for output: $!&quot;;


   # Set the width array
   #
   my @SubWords = ();
   @SubWords = @{$HDistAry{ $width }};

   my $Wlen = @SubWords;
   my $res  = 0;

   foreach my $Owd (@SubWords) 
   {
      my @DiffAry = ();
      push ( @DiffAry, $Owd );

      my @Ochrs = split ( //, $Owd );

      for ( my $i = 0; $i &lt; $Wlen; $i++ )
      {
         my $Twd = $SubWords[ $i ];   # check this target word for diff against obj word

         my @Tchrs = split ( //, $Twd );
         my $dcnt = 0;
         my $tlen = @Tchrs;

         for ( my $k = 0; $k &lt; $tlen &amp;&amp; $dcnt &lt; 2; $k++ )
         {
            if ( $Tchrs[ $k ] ne $Ochrs[ $k ] )
            {
                if ( ++$dcnt &gt; 1 ) {
                   $k = $tlen;
                }
            }
         }
         if ( $dcnt == 1 )
         {
             # found a diff by one char, push the target word
             push ( @DiffAry, $Twd );
         }
      }

      ### PRINT array of difs-by-one of the current word $Owd from the @AllLines array
      if ( @DiffAry &gt; 1 )
      {
         my $difout = join(&quot; - &quot;, @DiffAry);
         if ( $quiet == 0 ) {
            print &quot;$difout\n&quot;;
         }
         print $fho &quot;$difout\n&quot;;
         $res = 1;
      }
   }
   close ($fho);

   # Check if anything was written to the intermediate file
   #
   if ( $res == 0 ) {
      print (&quot;Diffs-by-one results:  None found \n&quot; );
      unlink( $fout );
   }

   # Check if we should spawn the query script wit this intermediate file
   #
   if ( $res == 1 &amp;&amp; $rxstr ne '' )
   {
      my $script = &quot;Cross_Qry.pl&quot;;
      my @args = ( &quot;In=$fout&quot;, &quot;rx=$rxstr&quot; );
     if ( $quiet == 1 ) {
         push (@args, &quot;quiet&quot; );
      }
      push (@args,  &quot;Out=$pre_fout&quot; . &quot;Ltr&quot;);  
      system($^X, $script, @args);
   }

}


### End ###
</code></pre>
<p>Cross_Qry.pl</p>
<pre><code># Cross_Qry.pl
# (single pass query filter)

use strict;
use warnings;

##############################################################################
# This will query an input Intermediate file given the input filter regex.
# An intermediate file is a file constructed with 'Cross.pl'.
# Each file contains fixed width words, ex. 7 letters wide.
# Each line contain a seed word (left column) followed by ALL words that differ
# by one letter from only the seed word. 
# Example:  ablare - ablate - ablaze - aflare - aglare
#  ----------
# These intermediate files need only be generated once.
# There is pre-generated list on my website.
# They are the superset used for lightning fast specific subset query's.
###############################################################################


my $usage = 
 &quot;\nUsage: Cross_Qry.pl \n\n&quot;.
 &quot;  Reqd:  &lt;In=Intermediate-file-name.txt&gt;\n&quot;.
 &quot;         &lt;rx=[st]&gt;  regex filter\n&quot;.
 &quot;  Opt:   &lt;Out=file-capture-root&gt;  prepended to '_Filt.txt' output name\n&quot;.
 &quot;         &lt;quiet&gt;   supress word list display of generated difs\n&quot;
;

if ( @ARGV &lt; 2 ) {
  die ( $usage );
}

my ($fname, $out, $rxstr, $quiet) = (&quot;&quot;, &quot;&quot;, &quot;&quot;, 0);
my $p;

for ( $p = 0; $p &lt; @ARGV; $p++ ) {   # Get intermediate file name
   if ( $ARGV[$p] =~ /(?i)^In=(.+)/ ) {
      $fname = $1;
      last;   
   }}
for ( $p = 0; $p &lt; @ARGV; $p++ ) {   # Get output file name seed
   if ( $ARGV[$p] =~ /(?i)^Out=(.+)/ ) {
      $out = $1;
      last;   
   }}
for ( $p = 0; $p &lt; @ARGV; $p++ ) {   # Get regex string
   if ( $ARGV[$p] =~ /(?i)^Rx=(.+)/ ) {
      $rxstr = $1;
      last;
   }}
for ( $p = 0; $p &lt; @ARGV; $p++ ) {   # Get quiet flag
   if ( $ARGV[$p] =~ /(?i)^quiet/ ) {
      $quiet = 1;
      last;   
   }}

if ( $fname eq &quot;&quot; ) {
   die ( &quot;$usage-------\nIntermediate file name required,  'In=...'\n&quot;);
}
if ( $rxstr eq &quot;&quot; ) {
   die ( &quot;$usage-------\nRegex filter string required,  'rx=...'\n&quot;);
}

# Compile imput regex string
#
my $rx = qr/$rxstr/;    # Regex to use to filter diff letter

# Open Intermediate file
#
open(my $fh, &quot;&lt;&quot;, $fname) or die &quot;\nCannot open intermediate file '$fname' for reading: $!&quot;;

my @AllLines = ();
my $start = 0;

while (my $line = &lt;$fh&gt;)
{
   chomp($line);
   $line =~ s/^\s+|\s+$//g;

   if ( $start &gt; 0 ) {
      push ( @AllLines, $line );
      # print $line, &quot;\n&quot;;
   }
   else {
      if ( $line =~ /^\S{3,} - \S{3,}/ ) {
         $start = 1;
      }
   }
}
close($fh); 

### HEADER ###

my $hdr = 
  &quot;\nQuery of Diffs-by-one using intermediate file\n :: input file :  $fname \n&quot; .
  &quot; :: filter :  rx = $rx \n&quot;;
if ( $out ne '' ) {
  $hdr .= &quot; :: output capture file :  $out&quot; . &quot;_Filt.txt\n&quot;;
} 
$hdr .= &quot;--------------------------------------------------------------\n&quot;; 

print $hdr;

# Open the output file
#
my $fho;

if ( $out ne '' )
{
   my $fout = $out . &quot;_Filt.txt&quot;;
   open($fho, &quot;+&gt;&quot;, $fout) or die &quot;Cannot open file '$fout' for output: $!&quot;;
   print $fho $hdr;
}


## QUERY BODY ##

my $res = 0;

foreach my $line (@AllLines) 
{
   my @LineWords = split( / - /, $line ); 
   my $Wlen = @LineWords;
   my @DiffAry = ();

   my $Owd = $LineWords[0];

   push ( @DiffAry, $Owd );   # push the seed object word

   my @Ochrs = split ( //, $Owd );  # split object word into letters

   for ( my $i = 1; $i &lt; $Wlen; $i++ )
   {
      my $Twd = $LineWords[ $i ];   # check this target word for diff against obj word

      my @Tchrs = split ( //, $Twd );
      my $dcnt = 0;
      my $dfiltcnt = 0;
      my $tlen = @Tchrs;

      for ( my $k = 0; $k &lt; $tlen &amp;&amp; $dcnt &lt; 2; $k++ )
      {
         if ( $Tchrs[ $k ] ne $Ochrs[ $k ] )
         {
             if ( ++$dcnt &gt; 1 ) {
                $k = $tlen;
             }
             elsif ( $Tchrs[$k] =~ $rx &amp;&amp; $Ochrs[$k] =~ $rx ) {
                ++$dfiltcnt;
             }
         }
      }
      if ( $dcnt == 1 &amp;&amp; $dfiltcnt == 1 )
      {
          # Based on filter regex, found a diff by one char, push the target word
          push ( @DiffAry, $Twd );
      }
   }

   ### PRINT array of difs-by-one of the current word $Owd from the @AllWirds array
   if ( @DiffAry &gt; 1 )
   {
      my $difout = join(&quot; - &quot;, @DiffAry);
      if ( $quiet != 1 ) {
         print &quot;$difout\n&quot;;
      }
      print $fho &quot;$difout\n&quot;  if ( $out ne '' );
      $res = 1;
   }
}

if ( $res == 0 ) {
   print (&quot;Query results:  None found \n&quot; );
   print $fho &quot;Query results:  None found \n&quot;  if ( $out ne '' );
}

